"checkout.session.completed"
| "checkout.session.async_payment_succeeded" ->
  handle_checkout_completed(...)
"checkout.session.expired" ->
  handle_checkout_failed(config, event_id, session_id, vacancy_id)
// Unknown event type — ack without claiming. We only consume
// a row in `processed_stripe_event` for events we actually
// handle, so a future arm can be added without retroactively
// marking historical events as processed.
_ -> wisp.json_response("{}", 200)

// M-1 gate. Anything other than "paid" is a payment that hasn't
// settled (async method in flight, failed, or a structurally
// missing field). Claim the event so a Stripe replay is a
// Duplicate, then stop: no complete_payment, no unlock, no
// burst scoring, no audit. The row stays `pending` — that IS
// the deterministic waiting state — and the vacancy stays
// locked. Ack 200 below so Stripe doesn't retry-storm.
case payment_status {
  "paid" ->
    run_completed_side_effects(...)
  _ -> Ok(PendingPayment)
}
